"""Bind an autocuda run to its harness sessions and find their session logs."""

from __future__ import annotations

import json
import os
import re
import stat
import sys
import tempfile
import uuid
from collections import deque
from collections.abc import Callable, Iterator, Sequence
from contextlib import contextmanager
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path, PurePosixPath
from typing import Any

CLAUDE_SESSION_ID_ENV = "CLAUDE_CODE_SESSION_ID"
CODEX_THREAD_ID_ENV = "CODEX_THREAD_ID"
PI_SESSION_FILE_ENV = "PI_SESSION_FILE"
PI_SESSION_DIR_ENV = "PI_SESSION_DIR"
HARNESSES = ("claude-code", "codex", "pi")
_SAFE_ID = re.compile(r"^[A-Za-z0-9](?:[A-Za-z0-9._-]{0,253}[A-Za-z0-9])?$")


def _canonical_session_id(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    try:
        parsed = uuid.UUID(value)
    except ValueError:
        return None
    return str(parsed)


def _pi_session_id(value: object) -> str | None:
    return value if isinstance(value, str) and _SAFE_ID.fullmatch(value) else None


def _harness_session_id(harness: str, value: object) -> str | None:
    return _pi_session_id(value) if harness == "pi" else _canonical_session_id(value)


def session_storage_root(harness: str) -> Path:
    if harness == "claude-code":
        root = Path(os.environ.get("CLAUDE_CONFIG_DIR", Path.home() / ".claude"))
    elif harness == "codex":
        root = Path(os.environ.get("CODEX_HOME", Path.home() / ".codex"))
    elif harness == "pi":
        root = Path(os.environ.get(PI_SESSION_DIR_ENV, Path.home() / ".pi/agent/sessions"))
    else:
        raise ValueError(f"unknown harness {harness!r}")
    return root.expanduser().absolute()


def _regular_file_anywhere(path: Path, label: str) -> Path:
    try:
        resolved = path.resolve(strict=True)
        info = path.lstat()
    except OSError as exc:
        raise ValueError(f"{label} does not exist at {path}") from exc
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISREG(info.st_mode):
        raise ValueError(f"{label} is not a regular file: {path}")
    return resolved


def _regular_file(path: Path, root: Path, label: str) -> Path:
    resolved = _regular_file_anywhere(path, label)
    try:
        resolved.relative_to(root.resolve(strict=True))
    except (OSError, ValueError) as exc:
        raise ValueError(f"{label} is outside {root}") from exc
    return resolved


def _records(path: Path, label: str) -> Iterator[dict[str, Any]]:
    found = False
    try:
        with path.open("rb") as stream:
            for number, raw_line in enumerate(stream, 1):
                if not raw_line.strip():
                    continue
                try:
                    record = json.loads(raw_line.decode("utf-8"))
                except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                    if not raw_line.endswith(b"\n"):
                        break
                    raise ValueError(
                        f"{label} has malformed JSON on line {number}: {path}"
                    ) from exc
                if not isinstance(record, dict):
                    raise ValueError(f"{label} has a non-object record on line {number}: {path}")
                found = True
                yield record
    except OSError as exc:
        raise ValueError(f"could not read {label}: {path}") from exc
    if not found:
        raise ValueError(f"{label} is empty: {path}")


def _first(path: Path, label: str) -> dict[str, Any]:
    return next(_records(path, label))


def _relative(root: Path, path: Path) -> str:
    return path.relative_to(root.resolve()).as_posix()


def _claude_main(root: Path, session_id: str) -> Path:
    candidates = [
        _regular_file(path, root, "Claude Code session")
        for path in root.glob(f"projects/*/{session_id}.jsonl")
        if not path.is_symlink() and path.is_file()
    ]
    if len(candidates) != 1:
        raise ValueError(f"Claude Code session {session_id} is missing or ambiguous")
    if not any(
        record.get("sessionId") == session_id
        for record in _records(candidates[0], "Claude Code session")
    ):
        raise ValueError("Claude Code session ID does not match its JSONL")
    return candidates[0]


def _codex_header(path: Path) -> tuple[str, str | None] | None:
    try:
        first = _first(path, "Codex session")
    except ValueError:
        return None
    payload = first.get("payload")
    if first.get("type") != "session_meta" or not isinstance(payload, dict):
        return None
    session_id = _canonical_session_id(payload.get("id"))
    if session_id is None:
        return None
    parent: str | None = None
    source = payload.get("source")
    if isinstance(source, dict):
        subagent = source.get("subagent")
        spawn = subagent.get("thread_spawn") if isinstance(subagent, dict) else None
        if isinstance(spawn, dict) and "parent_thread_id" in spawn:
            parent = _canonical_session_id(spawn.get("parent_thread_id"))
            if parent is None:
                return None
    return session_id, parent


def _codex_main(root: Path, session_id: str) -> Path:
    candidates: list[Path] = []
    sessions = root / "sessions"
    if sessions.is_dir():
        for path in sessions.rglob(f"*-{session_id}.jsonl"):
            if path.is_symlink() or not path.is_file():
                continue
            resolved = _regular_file(path, root, "Codex session")
            header = _codex_header(resolved)
            if header is not None and header[0] == session_id:
                candidates.append(resolved)
    if len(candidates) != 1:
        raise ValueError(f"Codex session {session_id} is missing or ambiguous")
    return candidates[0]


def _pi_header(path: Path) -> tuple[str, Path | None] | None:
    try:
        first = _first(path, "Pi session")
    except ValueError:
        return None
    session_id = _pi_session_id(first.get("id"))
    if first.get("type") != "session" or session_id is None:
        return None
    raw_parent = first.get("parentSession")
    if raw_parent is None:
        parent = None
    elif isinstance(raw_parent, str) and Path(raw_parent).is_absolute():
        parent = Path(raw_parent).resolve()
    else:
        return None
    return session_id, parent


def _pi_main(root: Path, value: object) -> tuple[str, Path]:
    if not isinstance(value, str) or not value:
        raise ValueError(f"${PI_SESSION_FILE_ENV} is empty")
    path = Path(value).expanduser()
    if not path.is_absolute():
        raise ValueError(f"${PI_SESSION_FILE_ENV} must be an absolute path")
    path = _regular_file(path, root, "Pi session")
    header = _pi_header(path)
    if header is None:
        raise ValueError("Pi session has an invalid header")
    return header[0], path


def _current_main_source(required: bool = True) -> dict[str, str] | None:
    available: list[tuple[str, str]] = []
    for harness, name in (
        ("claude-code", CLAUDE_SESSION_ID_ENV),
        ("codex", CODEX_THREAD_ID_ENV),
        ("pi", PI_SESSION_FILE_ENV),
    ):
        if os.environ.get(name):
            available.append((harness, name))
    if not available:
        if required:
            raise ValueError("no active Claude Code, Codex, or Pi session identity is set")
        return None
    if len(available) != 1:
        raise ValueError("multiple harness session identities are set")
    harness, env_name = available[0]
    root = session_storage_root(harness)
    if harness == "pi":
        session_id, path = _pi_main(root, os.environ[env_name])
    else:
        session_id = _canonical_session_id(os.environ[env_name])
        if session_id is None:
            raise ValueError(f"${env_name} is not a canonical session UUID")
        path = (
            _claude_main(root, session_id)
            if harness == "claude-code"
            else _codex_main(root, session_id)
        )
    return {
        "harness": harness,
        "session_id": session_id,
        "relative_path": _relative(root, path),
    }


def preflight_current_main_session() -> dict[str, str]:
    source = _current_main_source(required=True)
    assert source is not None
    return source


def sessions_dir(autocuda_root: Path) -> Path:
    directory = autocuda_root / "sessions"
    try:
        info = directory.lstat()
    except FileNotFoundError:
        return directory
    except OSError as exc:
        raise ValueError(f"sessions path is not a real directory: {directory}") from exc
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
        raise ValueError(f"sessions path is not a real directory: {directory}")
    return directory


def tagged_session_path(autocuda_root: Path, tag: str) -> Path:
    return sessions_dir(autocuda_root) / f"{tag}-sessions.json"


def _validate_current_source(raw: object) -> dict[str, str]:
    if not isinstance(raw, dict) or set(raw) != {"harness", "session_id", "relative_path"}:
        raise ValueError("session source has an invalid shape")
    harness = raw.get("harness")
    session_id = _harness_session_id(str(harness), raw.get("session_id"))
    relative_path = raw.get("relative_path")
    if harness not in HARNESSES or session_id is None:
        raise ValueError("session source has an invalid identity")
    if not isinstance(relative_path, str):
        raise ValueError("session source has an invalid path")
    relative = PurePosixPath(relative_path)
    if (
        relative.is_absolute()
        or relative.suffix != ".jsonl"
        or relative.as_posix() != relative_path
        or any(part in ("", ".", "..") for part in relative.parts)
    ):
        raise ValueError("session source has an invalid path")
    return {
        "harness": harness,
        "session_id": session_id,
        "relative_path": relative_path,
    }


def _canonical_started_at(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        return None
    return parsed.astimezone(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")


def _validate_source(raw: object) -> dict[str, str]:
    if not isinstance(raw, dict) or set(raw) != {
        "harness",
        "session_id",
        "relative_path",
        "started_at",
    }:
        raise ValueError("session source has an invalid shape")
    source = _validate_current_source(
        {key: raw[key] for key in ("harness", "session_id", "relative_path")}
    )
    started_at = _canonical_started_at(raw.get("started_at"))
    if started_at is None:
        raise ValueError("session source has an invalid start timestamp")
    return {**source, "started_at": started_at}


def _started_at() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")


def _recorded_source(source: dict[str, str]) -> dict[str, str]:
    return {**source, "started_at": _started_at()}


def _same_session(left: dict[str, str], right: dict[str, str]) -> bool:
    return all(left[key] == right[key] for key in ("harness", "session_id"))


def _same_source(left: dict[str, str], right: dict[str, str]) -> bool:
    return all(left[key] == right[key] for key in ("harness", "session_id", "relative_path"))


def _is_resume_retry(
    entries: Sequence[dict[str, str]],
    requested: dict[str, str],
) -> bool:
    return bool(entries) and _same_source(entries[-1], requested)


@dataclass(frozen=True)
class _LoadedSessionLedger:
    raw_bytes: bytes
    entries: tuple[dict[str, str], ...]


def _load_tagged_session_ledger(
    autocuda_root: Path,
    tag: str,
) -> _LoadedSessionLedger:
    path = tagged_session_path(autocuda_root, tag)
    try:
        descriptor = os.open(
            path,
            os.O_CLOEXEC | os.O_NONBLOCK | os.O_NOFOLLOW | os.O_RDONLY,
        )
    except FileNotFoundError:
        raise ValueError(f"tagged session record is missing for tag {tag}") from None
    except OSError as exc:
        raise ValueError(f"tagged session record is not a regular file: {path}") from exc
    try:
        with os.fdopen(descriptor, "rb") as stream:
            if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
                raise ValueError(f"tagged session record is not a regular file: {path}")
            raw_bytes = stream.read()
    except ValueError:
        raise
    except OSError as exc:
        raise ValueError(f"tagged session record is malformed for tag {tag}") from exc
    try:
        raw = json.loads(raw_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError(f"tagged session record is malformed for tag {tag}") from exc
    if not isinstance(raw, list) or not raw:
        raise ValueError(
            f"tagged session record is malformed for tag {tag}: expected a nonempty array"
        )
    try:
        entries = [_validate_source(item) for item in raw]
        for index, entry in enumerate(entries):
            if any(_same_session(entry, earlier) for earlier in entries[:index]):
                raise ValueError("tagged session ledger replays a prior session")
    except ValueError as exc:
        raise ValueError(f"tagged session record is malformed for tag {tag}: {exc}") from exc
    return _LoadedSessionLedger(raw_bytes, tuple(entries))


def load_tagged_sessions(autocuda_root: Path, tag: str) -> list[dict[str, str]]:
    return [dict(entry) for entry in _load_tagged_session_ledger(autocuda_root, tag).entries]


def _entry_path(entry: dict[str, str]) -> Path:
    root = session_storage_root(entry["harness"])
    return _regular_file(root / entry["relative_path"], root, "recorded main session")


def _write_tagged_sessions(
    path: Path,
    entries: list[dict[str, str]],
    directory_fd: int,
) -> None:
    temporary: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            "w",
            encoding="utf-8",
            dir=path.parent,
            prefix=f".{path.name}.",
            delete=False,
        ) as stream:
            temporary = Path(stream.name)
            stream.write(json.dumps(entries, indent=2, sort_keys=True) + "\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        temporary = None
        try:
            os.fsync(directory_fd)
        except OSError as exc:
            try:
                print(
                    f"warning: session ledger committed, but directory durability is uncertain: {exc}",
                    file=sys.stderr,
                )
            except Exception:
                pass
    except BaseException:
        if temporary is not None:
            try:
                temporary.unlink(missing_ok=True)
            except OSError:
                pass
        raise


@contextmanager
def _lock_tagged_sessions(path: Path) -> Iterator[int]:
    import fcntl  # noqa: PLC0415 — directory flock is Linux-only

    try:
        descriptor = os.open(
            path.parent,
            os.O_CLOEXEC | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_RDONLY,
        )
    except FileNotFoundError:
        raise ValueError(f"tagged session record is missing for tag {path.name[:-14]}") from None
    except OSError as exc:
        raise ValueError(f"sessions path is not a real directory: {path.parent}") from exc
    try:
        fcntl.flock(descriptor, fcntl.LOCK_EX)
        yield descriptor
    finally:
        os.close(descriptor)


def _resume_manager_session(
    autocuda_root: Path,
    tag: str,
    source: dict[str, str],
    validate_run: Callable[[], None],
) -> dict[str, str]:
    """Validate and append one manager session under the session lock."""
    entry = _validate_current_source(source)
    path = tagged_session_path(autocuda_root, tag)
    before = _load_tagged_session_ledger(autocuda_root, tag)

    with _lock_tagged_sessions(path) as directory_fd:
        ledger = _load_tagged_session_ledger(autocuda_root, tag)
        if ledger.raw_bytes != before.raw_bytes:
            if _is_resume_retry(ledger.entries, entry):
                return dict(ledger.entries[-1])
            raise ValueError(f"tag {tag} session ledger changed while waiting to resume")

        entries = [dict(existing) for existing in ledger.entries]

        for existing in entries:
            _entry_path(existing)
        try:
            validate_run()
        except ValueError:
            raise
        except (KeyError, OSError, TypeError) as exc:
            raise ValueError(f"run state is malformed for tag {tag}: {exc}") from exc

        current = _current_main_source(required=True)
        if current != entry:
            raise ValueError("active harness session changed after preflight")
        reloaded = _load_tagged_session_ledger(autocuda_root, tag)
        if reloaded.raw_bytes != ledger.raw_bytes:
            if _is_resume_retry(reloaded.entries, entry):
                return dict(reloaded.entries[-1])
            raise ValueError(f"tag {tag} session ledger changed while resuming")
        if _is_resume_retry(entries, entry):
            return entries[-1]
        if any(_same_session(entry, existing) for existing in entries):
            raise ValueError(f"tag {tag} cannot replay an earlier manager session")
        recorded = _recorded_source(entry)
        entries.append(recorded)
        try:
            _write_tagged_sessions(path, entries, directory_fd)
        except OSError as exc:
            raise ValueError(f"could not update session ledger for tag {tag}: {exc}") from exc
        return recorded


def record_resolved_main_session(
    autocuda_root: Path,
    tag: str,
    source: dict[str, str],
) -> dict[str, str]:
    entry = _validate_current_source(source)
    current = _current_main_source(required=True)
    if current != entry:
        raise ValueError("active harness session changed after preflight")
    path = tagged_session_path(autocuda_root, tag)
    path.parent.mkdir(parents=True, exist_ok=True)
    with _lock_tagged_sessions(path) as directory_fd:
        if path.exists() or path.is_symlink():
            entries = load_tagged_sessions(autocuda_root, tag)
            if len(entries) == 1 and _same_source(entries[0], entry):
                return entries[0]
            raise ValueError(f"tag {tag} already has a session ledger")
        else:
            entries = [_recorded_source(entry)]
        _write_tagged_sessions(path, entries, directory_fd)
        return entries[0]


